pub fn tables_for_language(language: GmsLanguage) -> &'static GmsTables {
    match language {
        GmsLanguage::English => &GMS_TABLES[0],
        GmsLanguage::French => &GMS_TABLES[1],
        GmsLanguage::German => &GMS_TABLES[2],
        GmsLanguage::Spanish => &GMS_TABLES[3],
        GmsLanguage::Italian => &GMS_TABLES[4],
        GmsLanguage::Chinese => &GMS_TABLES[5],
        GmsLanguage::Japanese => &GMS_TABLES[6],
        GmsLanguage::Korean => &GMS_TABLES[7],
        GmsLanguage::Portuguese => &GMS_TABLES[8],
        GmsLanguage::Russian => &GMS_TABLES[9],
    }
}

pub fn tables_for_code(code: &str) -> Option<&'static GmsTables> {
    GMS_TABLES
        .iter()
        .find(|tables| tables.code.eq_ignore_ascii_case(code))
}
